723	+//! Reads that tell "not there" from "could not look".
724	+//!
725	+//! `Path::exists` and `read_to_string(..).ok()` answer "absent" for a permission error, invalid UTF-8 or a loop. Code
726	+//! that decides what a release contains must not take those for a missing file.
727	+
728	+use std::io;
729	+use std::path::Path;
730	+
731	+/// The text of `path`, or `None` only when it does not exist. A permission error, a directory or invalid UTF-8 is an error.
732	+///
733	+/// # Errors
734	+///
735	+/// Any I/O error other than the file being absent.
736	+pub fn read_optional(path: &Path) -> io::Result<Option<String>> {
737	+    match std::fs::read_to_string(path) {
738	+        Ok(text) => Ok(Some(text)),
739	+        Err(error) if is_absent(&error) => Ok(None),
740	+        Err(error) => Err(error),
741	+    }
742	+}
743	+
744	+/// Nothing at the path, or a regular file where a parent directory should be: either way the path holds nothing.
745	+fn is_absent(error: &io::Error) -> bool {
746	+    matches!(error.kind(), io::ErrorKind::NotFound | io::ErrorKind::NotADirectory)
747	+}
748	+
749	+/// Whether `path` exists. A parent that cannot be searched is an error, not `false`.
750	+///
751	+/// # Errors
752	+///
753	+/// Any I/O error other than the path being absent.
754	+pub fn exists(path: &Path) -> io::Result<bool> {
755	+    match path.try_exists() {
756	+        Err(error) if is_absent(&error) => Ok(false),
757	+        result => result,
758	+    }
759	+}
