        }

        if !deferred_deletions.is_empty() {
            let deferred: Vec<&PathBuf> = deferred_deletions.iter().collect();
            run_git_on_paths(runner, root, &["rm", "--cached", "--ignore-unmatch", "--"], &deferred)?;

